import { ChevronRight } from "lucide-react";
import { cn } from "@/lib/cn";

// KMP-C25 (specs/KMP-C25-slot-picker-row.md). Inside an open day accordion panel. Pressing it places the dish in the slot
// immediately: no confirmation, no warning, and nothing here knows about role, season or recent cooking.

export type SlotPickerRowProps = {
  /** Fixed word: Breakfast, Snack 1, Main meal or Snack 2. */
  slot: string;
  /** What the slot holds now, verbatim (any script, may contain commas). */
  dish: string;
  dishLang?: string;
  onSelect: () => void;
  className?: string;
};

export function SlotPickerRow({ slot, dish, dishLang, onSelect, className }: SlotPickerRowProps) {
  return (
    <button
      type="button"
      onClick={onSelect}
      // The name carries both the slot and what is replaced. No wording about mismatch or replacing.
      aria-label={`${slot}, currently ${dish}`}
      className={cn(
        "group flex min-h-control w-full items-center justify-between gap-gap-md rounded-slot border-border-subtle bg-surface-raised px-inset-md py-3 text-start font-body leading-normal",
        "[&:not(:first-child)]:border-t-bw-default active:bg-surface-sunken",
        // edge-attached target: the ring is drawn inside (conventions 4.1)
        "focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring-inside focus-visible:outline-focus-ring",
        className,
      )}
    >
      <span className="flex min-w-0 flex-col">
        <span className="text-ui-floor font-semibold text-text-muted">{slot}</span>
        <span lang={dishLang} className="text-ui-body font-medium text-text [overflow-wrap:anywhere] group-hover:underline">
          {dish}
        </span>
      </span>
      <ChevronRight aria-hidden="true" className="size-icon-lg shrink-0 text-primary-text group-active:text-text-muted" />
    </button>
  );
}
